begin;
create table if not exists public.mme_crm_customers(customer_id uuid primary key default gen_random_uuid(),customer_number text not null unique,auth_user_id uuid unique,first_name text not null,last_name text not null,email text,phone text,preferred_contact_method text check(preferred_contact_method in('email','phone','sms','none')),marketing_consent boolean not null default false,consent_recorded_at timestamptz,customer_status text not null default 'active' check(customer_status in('active','inactive','do_not_contact','blocked')),assigned_rep_auth_user_id uuid,source text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(marketing_consent=false or consent_recorded_at is not null));
create unique index if not exists mme_crm_customers_email_lower_uq on public.mme_crm_customers(lower(email)) where email is not null;
create index if not exists mme_crm_customers_phone_idx on public.mme_crm_customers(phone) where phone is not null;
create table if not exists public.mme_crm_leads(lead_id uuid primary key default gen_random_uuid(),lead_number text not null unique,customer_id uuid references public.mme_crm_customers(customer_id),lead_name text not null,email text,phone text,source text,interest text,lead_status text not null default 'new' check(lead_status in('new','contacted','qualified','proposal','won','lost','disqualified')),priority text not null default 'normal' check(priority in('low','normal','high','urgent')),assigned_rep_auth_user_id uuid,estimated_value numeric(16,2) check(estimated_value is null or estimated_value>=0),next_follow_up_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_crm_interactions(interaction_id uuid primary key default gen_random_uuid(),customer_id uuid references public.mme_crm_customers(customer_id),lead_id uuid references public.mme_crm_leads(lead_id),interaction_type text not null check(interaction_type in('call','email','sms','meeting','note','web_chat','store_visit')),direction text check(direction in('inbound','outbound','internal')),subject text,summary text not null,occurred_at timestamptz not null default now(),employee_auth_user_id uuid not null,recording_reference text,created_at timestamptz not null default now(),check(customer_id is not null or lead_id is not null));
create table if not exists public.mme_crm_tasks(task_id uuid primary key default gen_random_uuid(),customer_id uuid references public.mme_crm_customers(customer_id),lead_id uuid references public.mme_crm_leads(lead_id),title text not null,description text,due_at timestamptz not null,assigned_to_auth_user_id uuid not null,task_status text not null default 'open' check(task_status in('open','in_progress','completed','cancelled','overdue')),completed_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(customer_id is not null or lead_id is not null));
create table if not exists public.mme_crm_support_tickets(ticket_id uuid primary key default gen_random_uuid(),ticket_number text not null unique,customer_id uuid not null references public.mme_crm_customers(customer_id),subject text not null,description text not null,category text not null default 'general',priority text not null default 'normal' check(priority in('low','normal','high','urgent')),ticket_status text not null default 'open' check(ticket_status in('open','in_progress','waiting_customer','resolved','closed')),assigned_to_auth_user_id uuid,order_reference text,warranty_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.mme_crm_ticket_messages(message_id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.mme_crm_support_tickets(ticket_id),author_auth_user_id uuid not null,internal_note boolean not null default false,message text not null,created_at timestamptz not null default now());
create table if not exists public.mme_crm_customer_tags(customer_tag_id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.mme_crm_customers(customer_id),tag text not null,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(customer_id,tag));
create table if not exists public.mme_crm_audit_events(event_id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,action text not null,actor_auth_user_id uuid not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.mme_crm_record_interaction(p_customer uuid,p_lead uuid,p_type text,p_direction text,p_subject text,p_summary text,p_actor uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare i uuid;
begin
 if p_customer is null and p_lead is null then raise exception 'customer_or_lead_required'; end if;
 if p_type not in('call','email','sms','meeting','note','web_chat','store_visit') then raise exception 'invalid_interaction_type'; end if;
 if p_summary is null or length(trim(p_summary))=0 then raise exception 'interaction_summary_required'; end if;
 insert into public.mme_crm_interactions(customer_id,lead_id,interaction_type,direction,subject,summary,employee_auth_user_id) values(p_customer,p_lead,p_type,p_direction,p_subject,p_summary,p_actor) returning interaction_id into i;
 insert into public.mme_crm_audit_events(entity_type,entity_id,action,actor_auth_user_id,metadata) values('interaction',i,'interaction_recorded',p_actor,jsonb_build_object('customer_id',p_customer,'lead_id',p_lead,'type',p_type));
 return jsonb_build_object('interaction_id',i);
end;$$;
revoke all on function public.mme_crm_record_interaction(uuid,uuid,text,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_crm_record_interaction(uuid,uuid,text,text,text,text,uuid) to service_role;
do $$declare t text;begin foreach t in array array['mme_crm_customers','mme_crm_leads','mme_crm_interactions','mme_crm_tasks','mme_crm_support_tickets','mme_crm_ticket_messages','mme_crm_customer_tags','mme_crm_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;